from __future__ import annotations
import copy,base64
STATES={'home': ['top_stories', 'cookie_banner', 'cookie_corner', 'newsletter_dialog', 'menu_drawer', 'ad_notification'], 'news': ['world', 'uk', 'politics', 'most_read', 'region_menu', 'breaking_alert'], 'article': ['reading', 'share_menu', 'save_dialog', 'cookie_preferences', 'text_settings', 'advertisement'], 'live': ['latest', 'key_events', 'paused', 'notification_prompt', 'summary_panel', 'ended'], 'sport': ['headlines', 'scores', 'fixtures', 'results', 'team_picker', 'follow_dialog'], 'business': ['headlines', 'markets', 'economy', 'technology', 'market_filter', 'newsletter_dialog'], 'culture': ['features', 'film', 'music', 'books', 'gallery', 'newsletter_dialog'], 'travel': ['destinations', 'guides', 'food', 'sustainable', 'destination_picker', 'cookie_corner'], 'video': ['featured', 'playing', 'paused', 'captions', 'quality_menu', 'consent_dialog'], 'search': ['results', 'typing', 'filtered', 'no_results', 'filter_panel', 'saved_search_dialog']}
MODALS={'saved_search_dialog', 'save_dialog', 'cookie_preferences', 'follow_dialog', 'consent_dialog', 'newsletter_dialog'}
PANELS={'cookie_banner': 'cookie_banner', 'cookie_corner': 'cookie_corner', 'menu_drawer': 'drawer', 'ad_notification': 'ad', 'region_menu': 'menu', 'breaking_alert': 'toast', 'share_menu': 'share', 'text_settings': 'text', 'notification_prompt': 'permission', 'summary_panel': 'summary', 'team_picker': 'picker', 'market_filter': 'filter', 'destination_picker': 'picker', 'quality_menu': 'quality', 'filter_panel': 'filter', 'typing': 'suggestions'}
HEADLINES=['Cities rethink their streets as neighbourhood projects grow', 'Scientists map a changing coastline from the air', 'The library helping a community tell its own stories', 'Inside the workshop giving old materials a new life', 'A new generation of musicians finds an audience', 'How local markets are changing the way people shop', 'The quiet return of overnight train journeys', 'Researchers explore the future of urban gardens', 'What makes a public space work for everyone?', 'The photographers documenting everyday life', 'A mountain trail with a story at every turn', 'Why repair cafés are bringing neighbours together', 'The technology making archives easier to explore', 'A closer look at the week in science', 'How a small museum is reaching a wider world', 'The changing rhythms of a working harbour', 'Meet the volunteers protecting a local wetland', 'A guide to discovering art outside the gallery', 'The chefs preserving a regional food tradition', 'What the next chapter of city transport could look like', 'The communities rebuilding their green spaces', 'Five ideas shaping the future of work', 'The surprising history behind a familiar building', 'How young athletes prepare for the next season']
def illustration(i):
 colors=['#658b92','#a47a62','#77875c','#766c92','#ad8d50']
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450"><rect width="800" height="450" fill="{colors[i%5]}"/><circle cx="620" cy="100" r="65" fill="#f3e3bd"/><path d="M0 340L210 140L420 330L570 210L800 390V450H0Z" fill="#233f48"/><path d="M0 400L280 290L550 410L800 330V450H0Z" fill="#172b32"/></svg>'
 return 'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 rows=[{'title':t,'section':['World','Science','Culture','Business','Travel','Earth'][i%6],'summary':'Community projects, new research and the people behind the ideas. A fictional report created for this interface dataset.','time':str(i+1)+' hrs ago','image':illustration(i+sample_index)} for i,t in enumerate(HEADLINES)]
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'popup_mode':None,'keyboard_visible':False,'query':'community','rows':rows,'sample_index':sample_index}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d.update(state=state,popup_visible=state in MODALS,popup_mode='modal' if state in MODALS else PANELS.get(state),keyboard_visible=state=='typing')
 if state=='no_results':d['rows']=[]
 if state=='filtered':d['rows']=d['rows'][::3]
 return d
